              "- HS trao đổi và trả lời: Xúc giá thể dùng xẻng nhỏ; tưới nước dùng bình tưới; nhổ cỏ hoặc chạm vào đất nên đeo găng tay; bảo vệ tay cũng dùng găng tay."
